import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Sidebar from './components/Sidebar';

// Telas de cadastro
import CadastroAlunos from './telas/cadastros/CadastroAlunos';
import CadastroDisciplinas from './telas/cadastros/CadastroDisciplinas';
import CadastroProfessores from './telas/cadastros/CadastroProfessores';
import CadastroSalas from './telas/cadastros/CadastroSalas';
import CadastroTurmas from './telas/cadastros/CadastroTurmas';

// Telas de consulta
import ConsultaAlunos from './telas/consultas/ConsultaAlunos';
import ConsultaDisciplinas from './telas/consultas/ConsultaDisciplinas';
import ConsultaProfessores from './telas/consultas/ConsultaProfessores';
import ConsultaSalas from './telas/consultas/ConsultaSalas';
import ConsultaTurmas from './telas/consultas/ConsultaTurmas';

import Home from './telas/Home'; // Página inicial

function App() {
  return (
    <Router> {/* Envolva tudo com o Router */}
      <div style={{ display: 'flex' }}>
        <Sidebar />
        <div style={{ marginLeft: '250px', padding: '20px' }}>
          <Routes>
            {/* Rotas de cadastro */}
            <Route path="/cadastro/CadastroAlunos" element={<CadastroAlunos />} />
            <Route path="/cadastro/CadastroDisciplinas" element={<CadastroDisciplinas />} />
            <Route path="/cadastro/CadastroProfessores" element={<CadastroProfessores />} />
            <Route path="/cadastro/CadastroSalas" element={<CadastroSalas />} />
            <Route path="/cadastro/CadastroTurmas" element={<CadastroTurmas />} />

            {/* Rotas de consulta */}
            <Route path="/consulta/ConsultaAlunos" element={<ConsultaAlunos />} />
            <Route path="/consulta/ConsultaDisciplinas" element={<ConsultaDisciplinas />} />
            <Route path="/consulta/ConsultaProfessores" element={<ConsultaProfessores />} />
            <Route path="/consulta/ConsultaSalas" element={<ConsultaSalas />} />
            <Route path="/consulta/ConsultaTurmas" element={<ConsultaTurmas />} />

            {/* Página inicial */}
            <Route path="/" element={<Home />} />
          </Routes>
        </div>
      </div>
    </Router>
  );
}

export default App;
